public class Solution {
    public int dominantElement(int[] nums) {
        int candidate = nums[0];
        int count = 0;
        for (int x : nums) {
            if (count == 0) {
                candidate = x;
                count = 1;
            } else if (x == candidate) {
                count++;
            } else {
                count--;
            }
        }
        return candidate;
    }
}

